-- vyora-mcp — publication de l'artefact de aaf0783 (42 996 caractères, 10 tranches).
--
-- Pourquoi un nouveau fichier : la migration 20261120090200 portait déjà ce rôle et
-- avait été appliquée à sa version d'origine ; la rejouer telle quelle ne publie plus
-- rien. Le contenu ci-dessous est la copie exacte de ses tranches.
--
-- Portée : uniquement les lignes `name = 'vyora-mcp'` de public._edge_function_artifact_slices.
-- Les artefacts vyora-ai, vyora-oauth et vyora-provider-health ne sont pas touchés.
--
-- Étape 0 : l'artefact actuellement servi (v5, 5 tranches, sha256 6e54e12b…) est conservé
-- sous `vyora-mcp-rollback-20261114` pour permettre un retour arrière immédiat, sans
-- reconstruire quoi que ce soit.

delete from public._edge_function_artifact_slices where name = 'vyora-mcp-rollback-20261114';

insert into public._edge_function_artifact_slices(name, part, chunk)
select 'vyora-mcp-rollback-20261114', part, chunk
  from public._edge_function_artifact_slices
 where name = 'vyora-mcp';

do $backup$
declare parts integer; taille integer;
begin
  select count(*), sum(length(chunk)) into parts, taille
    from public._edge_function_artifact_slices where name = 'vyora-mcp-rollback-20261114';
  if parts <> 5 or taille <> 8888 then
    raise exception 'sauvegarde invalide : % tranches, % caractères (attendu 5 / 8888)',
      coalesce(parts, 0), coalesce(taille, 0);
  end if;
end
$backup$;

delete from public._edge_function_artifact_slices where name = 'vyora-mcp';

insert into public._edge_function_artifact_slices(name, part, chunk)
values
  ('vyora-mcp', 0, ''),
  ('vyora-mcp', 1, ''),
  ('vyora-mcp', 2, ''),
  ('vyora-mcp', 3, ''),
  ('vyora-mcp', 4, ''),
  ('vyora-mcp', 5, ''),
  ('vyora-mcp', 6, ''),
  ('vyora-mcp', 7, ''),
  ('vyora-mcp', 8, ''),
  ('vyora-mcp', 9, '');

do $artifact$
declare
  assembled text;
  parts integer;
begin
  select count(*), string_agg(chunk, '' order by part)
    into parts, assembled
  from public._edge_function_artifact_slices where name = 'vyora-mcp';

  if assembled is null or parts <> 10 then
    raise exception 'artefact % : % tranches publiées au lieu de %', 'vyora-mcp', coalesce(parts, 0), 10;
  end if;
  if exists (
    select 1 from public._edge_function_artifact_slices
    where name = 'vyora-mcp' and (part < 0 or part >= 10 or length(chunk) = 0 or length(chunk) > 2000)
  ) then
    raise exception 'artefact % : numérotation ou taille de tranche invalide', 'vyora-mcp';
  end if;
  if length(assembled) <> 18708 then
    raise exception 'artefact % : % caractères base64 au lieu de %', 'vyora-mcp', length(assembled), 18708;
  end if;
  if md5(assembled) <> '973eab430c3e7449ca4bc58e353d9a1d' then
    raise exception 'artefact % : empreinte des tranches différente', 'vyora-mcp';
  end if;
  raise notice 'artefact % publié : % caractères, % tranches, sha256 %', 'vyora-mcp', 42996, 10,
    '7e19ee1aa145ff44057bd1bb305b5eae8803d37700572f546eaf3af51414d8a3';
end
$artifact$;
